import React, { useState } from 'react';

function SearchFilter({ onApply, onClear, initial = {} }) {
  const [q, setQ] = useState(initial.q || '');
  const [type, setType] = useState(initial.type || '');
  const [status, setStatus] = useState(initial.status || '');
  const [minPrice, setMinPrice] = useState(initial.minPrice || '');
  const [maxPrice, setMaxPrice] = useState(initial.maxPrice || '');
  const [location, setLocation] = useState(initial.location || '');

  const apply = () => {
    onApply({ q, type, status, minPrice: minPrice ? Number(minPrice) : '', maxPrice: maxPrice ? Number(maxPrice) : '', location });
  };

  const clear = () => {
    setQ(''); setType(''); setStatus(''); setMinPrice(''); setMaxPrice(''); setLocation('');
    onClear();
  };

  return (
    <div className="card mb-4">
      <div className="card-body">
        <div className="row g-2">
          <div className="col-md-3">
            <input className="form-control" placeholder="بحث (وصف، حي، مالك)" value={q} onChange={e => setQ(e.target.value)} />
          </div>
          <div className="col-md-2">
            <select className="form-select" value={type} onChange={e => setType(e.target.value)}>
              <option value="">كل الأنواع</option>
              <option>شقة</option>
              <option>فيلا</option>
              <option>مكتب</option>
              <option>محل</option>
            </select>
          </div>
          <div className="col-md-2">
            <select className="form-select" value={status} onChange={e => setStatus(e.target.value)}>
              <option value="">كل الحالات</option>
              <option>للبيع</option>
              <option>للإيجار</option>
            </select>
          </div>
          <div className="col-md-2">
            <input type="number" className="form-control" placeholder="أقل سعر" value={minPrice} onChange={e => setMinPrice(e.target.value)} />
          </div>
          <div className="col-md-2">
            <input type="number" className="form-control" placeholder="أعلى سعر" value={maxPrice} onChange={e => setMaxPrice(e.target.value)} />
          </div>
          <div className="col-md-1 d-grid">
            <button className="btn btn-primary" onClick={apply}>تصفية</button>
            <button className="btn btn-link text-muted" onClick={clear}>مسح</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SearchFilter;
